#include <cstdio>

struct Empty {};                 // 空类，sizeof 至少为 1
struct Base  { int x; };

// 空基类作为基类时可以被"优化掉"，不占独立存储
struct WithEBO   : Empty, Base {};
// 空类作为普通成员时，必须占位置（C++17 及以前）
struct WithMember { int x; Empty e; };

int main() {
    printf("sizeof(Empty)=%zu sizeof(Base)=%zu\n", sizeof(Empty), sizeof(Base));
    printf("WithEBO sizeof=%zu\n", sizeof(WithEBO));
    printf("EBO 生效: %d\n", (int)(sizeof(WithEBO) == sizeof(Base)));
    printf("WithMember sizeof=%zu\n", sizeof(WithMember));
    return 0;
}
